using System.Text.Json;
using Bliss.Domain.CommandGateway;
using Npgsql;
namespace Bliss.Infrastructure.CommandGateway;
public sealed record GatewayTaskTransition(GatewayTaskSnapshot Snapshot,bool Replay);
// Local state bookkeeping, not an executor, agent evaluator or owner acceptance authority.
public sealed class LocalGatewayTaskLoop
{
 private readonly NpgsqlDataSource data;
 public LocalGatewayTaskLoop(NpgsqlDataSource data){var c=new NpgsqlConnectionStringBuilder(data.ConnectionString);if(c.Host!="127.0.0.1"||c.Database!="gateway_test")throw new InvalidOperationException("Loopback gateway_test required.");this.data=data;}
 private static GatewayTaskSnapshot Read(NpgsqlDataReader r)=>new(r.GetString(0),r.GetInt32(1),r.IsDBNull(2)?null:r.GetGuid(2),r.IsDBNull(3)?null:r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.IsDBNull(5)?null:r.GetInt32(5),r.IsDBNull(6)?null:r.GetInt32(6),r.IsDBNull(7)?null:r.GetString(7));
 public async Task<GatewayTaskTransition> Apply(Guid id,GatewayPrincipal p,GatewayTaskPolicy policy,CancellationToken ct=default)
 {
  GatewayTaskLoop.Authorize(p,policy);await using var c=await data.OpenConnectionAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await using(var limits=new NpgsqlCommand("SET LOCAL lock_timeout='2s'; SET LOCAL statement_timeout='5s'",c,tx))await limits.ExecuteNonQueryAsync(ct);
  await using var proof=new NpgsqlCommand("SELECT m.task_id,m.correlation_id,m.sender_agent_id,m.recipient_agent_id,m.causation_id,m.canonical_json FROM command_gateway.messages m JOIN command_gateway.acceptance_audit a ON a.message_id=m.message_id AND a.tenant_id=m.tenant_id AND a.actor_agent_id=m.sender_agent_id AND a.content_hash=m.content_hash JOIN command_gateway.outbox_intents o ON o.message_id=m.message_id AND o.tenant_id=m.tenant_id AND o.recipient_agent_id=m.recipient_agent_id WHERE m.message_id=@id AND m.tenant_id=@tenant AND m.sender_agent_id=@actor",c,tx);proof.Parameters.AddWithValue("id",id);proof.Parameters.AddWithValue("tenant",p.TenantId);proof.Parameters.AddWithValue("actor",p.AgentId);string task,json;Guid correlation,sender,recipient;Guid? cause;await using(var r=await proof.ExecuteReaderAsync(ct)){if(!await r.ReadAsync(ct))throw new UnauthorizedAccessException("Owned durable acceptance proof required.");task=r.GetString(0);correlation=r.GetGuid(1);sender=r.GetGuid(2);recipient=r.GetGuid(3);cause=r.IsDBNull(4)?null:r.GetGuid(4);json=r.GetString(5);}
  var control=await LocalGatewayBudget.Lock(c,tx,p.TenantId,ct);if(control.Stopped)throw new InvalidOperationException("Tenant stopped; no task advancement.");using var document=JsonDocument.Parse(json);var root=document.RootElement;var type=Enum.Parse<GatewayMessageType>(root.GetProperty("type").GetString()!);var expiry=root.GetProperty("expiresAt").GetDateTimeOffset();
  if(type==GatewayMessageType.DefectReport&&cause is null){await using var seed=new NpgsqlCommand("INSERT INTO command_gateway.task_runs(tenant_id,task_id,correlation_id,executive_agent_id,engineering_agent_id,stage,turns) VALUES(@tenant,@task,@correlation,@executive,@engineering,'NEW',0) ON CONFLICT DO NOTHING",c,tx);Bind(seed,p.TenantId,task,correlation);seed.Parameters.AddWithValue("executive",policy.ExecutiveAgentId);seed.Parameters.AddWithValue("engineering",policy.EngineeringAgentId);await seed.ExecuteNonQueryAsync(ct);}
  GatewayTaskSnapshot state;await using(var query=new NpgsqlCommand("SELECT stage,turns,last_message_id,commit_hash,evidence_hash,passed,failed,verdict,executive_agent_id,engineering_agent_id FROM command_gateway.task_runs WHERE tenant_id=@tenant AND task_id=@task AND correlation_id=@correlation FOR UPDATE",c,tx)){Bind(query,p.TenantId,task,correlation);await using var r=await query.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new InvalidOperationException("Task must start with registered defect report.");if(r.GetGuid(8)!=policy.ExecutiveAgentId||r.GetGuid(9)!=policy.EngineeringAgentId)throw new UnauthorizedAccessException("Current task role binding required.");state=Read(r);}
  await using(var prior=new NpgsqlCommand("SELECT stage,turn,message_id,commit_hash,evidence_hash,passed,failed,verdict FROM command_gateway.task_events WHERE message_id=@id AND tenant_id=@tenant AND actor_agent_id=@actor",c,tx)){prior.Parameters.AddWithValue("id",id);prior.Parameters.AddWithValue("tenant",p.TenantId);prior.Parameters.AddWithValue("actor",p.AgentId);await using var r=await prior.ExecuteReaderAsync(ct);if(await r.ReadAsync(ct))return new(Read(r),true);}
  await using(var now=new NpgsqlCommand("SELECT clock_timestamp()",c,tx)){if(expiry<=new DateTimeOffset((DateTime)(await now.ExecuteScalarAsync(ct))!))throw new InvalidOperationException("Expired accepted message cannot advance task.");}
  var next=GatewayTaskLoop.Advance(state,type,id,cause,sender,recipient,policy,root.GetProperty("payload"));await using(var update=new NpgsqlCommand("UPDATE command_gateway.task_runs SET stage=@stage,turns=@turn,last_message_id=@id,commit_hash=@commit,evidence_hash=@hash,passed=@passed,failed=@failed,verdict=@verdict WHERE tenant_id=@tenant AND task_id=@task AND correlation_id=@correlation",c,tx)){Bind(update,p.TenantId,task,correlation);Values(update,id,next);await update.ExecuteNonQueryAsync(ct);}
  await using(var audit=new NpgsqlCommand("INSERT INTO command_gateway.task_events(message_id,tenant_id,task_id,correlation_id,actor_agent_id,turn,stage,commit_hash,evidence_hash,passed,failed,verdict) VALUES(@id,@tenant,@task,@correlation,@actor,@turn,@stage,@commit,@hash,@passed,@failed,@verdict)",c,tx)){Bind(audit,p.TenantId,task,correlation);Values(audit,id,next);audit.Parameters.AddWithValue("actor",p.AgentId);await audit.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);return new(next,false);
 }
 private static void Bind(NpgsqlCommand cmd,Guid tenant,string task,Guid correlation){cmd.Parameters.AddWithValue("tenant",tenant);cmd.Parameters.AddWithValue("task",task);cmd.Parameters.AddWithValue("correlation",correlation);}
 private static void Values(NpgsqlCommand cmd,Guid id,GatewayTaskSnapshot s){cmd.Parameters.AddWithValue("id",id);cmd.Parameters.AddWithValue("stage",s.Stage);cmd.Parameters.AddWithValue("turn",s.Turns);cmd.Parameters.AddWithValue("commit",NpgsqlTypes.NpgsqlDbType.Text,(object?)s.CommitHash??DBNull.Value);cmd.Parameters.AddWithValue("hash",NpgsqlTypes.NpgsqlDbType.Text,(object?)s.EvidenceHash??DBNull.Value);cmd.Parameters.AddWithValue("passed",NpgsqlTypes.NpgsqlDbType.Integer,(object?)s.Passed??DBNull.Value);cmd.Parameters.AddWithValue("failed",NpgsqlTypes.NpgsqlDbType.Integer,(object?)s.Failed??DBNull.Value);cmd.Parameters.AddWithValue("verdict",NpgsqlTypes.NpgsqlDbType.Text,(object?)s.Verdict??DBNull.Value);}
}
